style.css:
/* Global Styles */
body {
  background-color: #1a1a1a; /* Dark background for the page */
  color: #00ff00; /* Neon green text */
  font-family: 'Courier New', Courier, monospace; /* Monospaced font for a terminal feel */
  text-align: center; /* Center align text for a neat look */
  overflow: hidden; /* Prevent overflow */
}

/* Background */
html {
  background: url('https://www.transparenttextures.com/patterns/hexagonal.png'), linear-gradient(45deg, #000000, #004400); /* Dark background with a subtle hexagonal pattern */
  background-size: 10px 10px;
  background-position: center;
}

/* Glitch Text Effect */
h1, h2, h3, h4, h5, h6, p {
  text-transform: uppercase;
  font-size: 2rem;
  letter-spacing: 0.2em;
  color: #00ff00;
  position: relative;
  display: inline-block;
  animation: glitch 1.5s infinite;
}

/* Glitch Animation */
@keyframes glitch {
  0% {
    text-shadow: 2px 2px 5px rgba(255, 255, 255, 0.1), -2px -2px 5px rgba(0, 255, 0, 0.4);
    transform: translateX(0);
  }
  25% {
    text-shadow: -2px 2px 5px rgba(255, 255, 255, 0.1), 2px -2px 5px rgba(0, 255, 0, 0.4);
    transform: translateX(2px);
  }
  50% {
    text-shadow: 2px -2px 5px rgba(255, 255, 255, 0.1), -2px 2px 5px rgba(0, 255, 0, 0.4);
    transform: translateX(-2px);
  }
  75% {
    text-shadow: -2px -2px 5px rgba(255, 255, 255, 0.1), 2px 2px 5px rgba(0, 255, 0, 0.4);
    transform: translateX(2px);
  }
  100% {
    text-shadow: 2px 2px 5px rgba(255, 255, 255, 0.1), -2px -2px 5px rgba(0, 255, 0, 0.4);
    transform: translateX(0);
  }
}

/* Adding a Neon Pulse Effect for Buttons */
button {
  background-color: #00ff00;
  color: #1a1a1a;
  border: 2px solid #00ff00;
  padding: 10px 20px;
  font-size: 1.2rem;
  font-weight: bold;
  border-radius: 5px;
  cursor: pointer;
  text-transform: uppercase;
  transition: all 0.3s ease;
}

button:hover {
  background-color: transparent;
  color: #00ff00;
  box-shadow: 0 0 15px #00ff00, 0 0 25px #00ff00, 0 0 35px #00ff00;
}

/* Glitch effect for input fields */
input[type="text"], input[type="password"], textarea {
  background-color: transparent;
  border: 2px solid #00ff00;
  color: #00ff00;
  font-family: 'Courier New', Courier, monospace;
  padding: 10px;
  font-size: 1rem;
  text-align: center;
}

input[type="text"]:focus, input[type="password"]:focus, textarea:focus {
  outline: none;
  border: 2px solid #ff0000;
  box-shadow: 0 0 10px #ff0000;
}

/* Adding animation to page elements */
@keyframes flicker {
  0% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
  100% {
    opacity: 1;
  }
}

h1, h2, h3 {
  animation: flicker 0.5s infinite alternate;
}
